DELETE FROM `dc_item_tooltip` WHERE `d3_id` IN ('HealthPotionLegendary_03', 'HealthPotionLegendary_01', 'HealthPotionLegendary_02', 'HealthPotionLegendary_04', 'HealthPotionLegendary_05', 'HealthPotionLegendary_06', 'P2_HealthPotionLegendary_07', 'HealthPotionLegendary_08', 'HealthPotionLegendary_09', 'HealthPotionLegendary_10', 'HealthPotionLegendary_11');
INSERT INTO `dc_item_tooltip` (`d3_id`, `set_id`, `power_text`, `flavour`) VALUES
('HealthPotionLegendary_03', '', 'Restores an additional 75000–100000 Life over 5 seconds.', '“Does Your Majesty know what would serve his armies better than mere healing? Healing combined with more healing!” -Royal Apothecary Jentulf, advising His Majesty in council.'),
('HealthPotionLegendary_01', '', 'Increases Armor by 10–20% for 5 seconds.', 'When Royal Apothecary Jentulf said "If only there were a way to lessen the need for healing," Royal Blacksmith Akmmenn replied "I have an idea."'),
('HealthPotionLegendary_02', '', 'Increases Resist All by 50–100 for 5 seconds.', '“It heals you, it helps you resist damage, and it cures warts!” -Royal Apothecary Jentulf, presenting his newest creation to the king.'),
('HealthPotionLegendary_04', '', 'Increases Life per Hit by 15000–20000 for 5 seconds.', '“I don’t know how it works, but it’s safe to say that I am the finest apothecary of our age.” -Royal Apothecary Jentulf, in his speech to the Society of Apothecaries.'),
('HealthPotionLegendary_05', '', 'Increases Life per Kill by 40000–50000 for 5 seconds.', '"Well, I had to test it on someone, didn''t I? You''re all just jealous!" -Royal Apothecary Jentulf at his trial, just before sentencing.'),
('HealthPotionLegendary_06', '', 'Drinking Kulle-Aid allows you to burst through walls summoned by Waller elites for 5 seconds.', 'Oh, yeah!'),
('P2_HealthPotionLegendary_07', '', 'Restores 20–30% resource when used below 50% health.', '"When you are losing a fight, healing is no help, as you''ll just lose that health in turn. No, what you need is a potion that gives you energy. And I know how to make that potion!" -Prisoner Jentulf, in a letter to the King pleading for early release.'),
('HealthPotionLegendary_08', '', 'Fears enemies within 12 yards for 3–4 seconds.', '“If I learned one thing from my years in the dungeons it’s this: fear is a great motivator. We all need some fear in our lives!” - Royal Apothecary Jentulf at his reinstatement ceremony.'),
('HealthPotionLegendary_09', '', 'Increases healing from all sources by 20–25% for 5 seconds.', '"Some of you claimed I lost the touch during my sojourn in the King''s dungeon. To you I say, this potion amplifies healing and puts the lie to your feckless assertions! Yes, I''m back, lackies!" -Royal Apothecary Jentulf in his weekly address to the Society of Apothecaries.'),
('HealthPotionLegendary_10', '', 'Teleport to another location based on your missing health. Results may vary.', '“In my workshop, when one sees liquid in a bottle, logic dictates that it is something beneficial. But bottle logic is wrong! My genius has transcended the beneficial. Now, I ride the waves of chaos. Chaos!” -Royal Apothecary Jentulf, in his final letter to the Society of Apothecaries, before his disappearance.'),
('HealthPotionLegendary_11', '', 'Become immune to control impairing effects for 5–7 seconds after drinking this potion.', 'Prevention is the best cure.');
